function _buildAuthHeaders(accessToken, requestId, requestTime, includeContentType) {
	var headers = [];
	headers.push(new Header("Authorization", "Bearer " + accessToken))
	headers.push(new Header("ClientId", CLIENT_ID));
	headers.push(new Header("ClientPassword", CLIENT_PASSWORD));
	headers.push(new Header("RequestId", requestId));
	headers.push(new Header("RequestTime", requestTime));
	headers.push(new Header("Content-Type", "application/json"));
	return headers;
}

// Safe wrapper for JSON POST. Always returns response/error object.
function _postJson(url, body, headers) {
	try {
		return lib.ESD_COMMON_HTTP.postJson(url, body, headers);
	} catch (e) {
		return {
			success: false,
			message: e && e.message ? e.message : String(e)
		};
	}
}

// Safe wrapper for POST without body, with best-effort JSON parsing.
function _postNoBodyJsonSafe(url, headers) {
	try {
		var resp = lib.ESD_COMMON_HTTP.postNoBody(url, headers);
		if (typeof resp === "string") {
			try {
				return JSON.parse(resp);
			} catch (e2) {
				return resp;
			}
		}
		return resp;
	} catch (e) {
		return {
			success: false,
			message: e && e.message ? e.message : String(e)
		};
	}
}

