function signRequestFileECM(params, isTest) {
	if (true) {
		var testParams = params || {};
		return {
			requestId: String(testParams.requestId || "test-request-id-001"),
			statusCode: "00",
			statusDesc: "Thành công",
			serverStatusCode: null,
			additionalStatus: null,
			data_to_be_signed: "OBJECT_ID_SIGNED_1743567890",
			transaction_id: "TXN_1743567890_001"
		};
	}

	params = params || {};
	if (!params.accessToken) {
		return { success: false, message: "accessToken is required" };
	}

	var requestId = params.requestId;
	var requestTime = params.requestTime;

	var body = params.body;

	body.requestId = body.requestId || requestId;

	var url = URL.signRequest;
	var headers = _buildAuthHeaders(params.accessToken, requestId, requestTime, false);
	return _postJson(url, JSON.stringify(body), headers);
}

